import fs from 'node:fs'
import { GAMES, MODS } from '@shared/catalog'

/**
 * Write the README's catalog table straight from the catalog.
 *
 * It writes the file rather than printing for pasting: the table drifted twice
 * from being regenerated by hand and once from being spliced while its own
 * bundle had been deleted, so the safe version is the one nobody has to
 * remember to copy.
 */

const START = '<!-- catalog:start -->'
const END = '<!-- catalog:end -->'

const gameName = new Map(GAMES.map((game) => [game.id, game.name]))

function sourceLabel(mod: (typeof MODS)[number]): string {
  if (mod.source.kind === 'github') return 'GitHub'
  try {
    return new URL(mod.source.url).hostname.replace(/^www\./, '')
  } catch {
    return 'manual'
  }
}

function installLabel(mod: (typeof MODS)[number]): string {
  if (mod.install.installer) return 'runs its setup'
  if (mod.install.steps.length === 0) return 'guide only'
  return mod.source.kind === 'manual' ? 'manual download' : 'yes'
}

function buildTable(): string {
  const rows = MODS.map((mod) => {
    const cells = [
      gameName.get(mod.gameId) ?? mod.gameId,
      mod.name,
      mod.author,
      mod.maturity,
      sourceLabel(mod),
      installLabel(mod),
    ]
    return `| ${cells.join(' | ')} |`
  })

  return [
    '| Game | Mod | Author | Maturity | Source | Auto-install |',
    '|---|---|---|---|---|---|',
    ...rows,
    '',
    `${GAMES.length} games, ${MODS.length} mods.`,
  ].join('\n')
}

const table = buildTable()
const readme = fs.readFileSync('README.md', 'utf8')

const start = readme.indexOf(START)
const end = readme.indexOf(END)
if (start === -1 || end === -1) {
  console.error(`README.md is missing the ${START} / ${END} markers.`)
  process.exit(1)
}

const updated = readme.slice(0, start + START.length) + '\n' + table + '\n' + readme.slice(end)
if (updated === readme) {
  console.log(`README table already current (${GAMES.length} games, ${MODS.length} mods).`)
} else {
  fs.writeFileSync('README.md', updated)
  console.log(`README table updated: ${GAMES.length} games, ${MODS.length} mods.`)
}
